package lk.gov.health.govcare.ai;
import lk.gov.health.govcare.common.*; import lk.gov.health.govcare.security.*; import org.springframework.stereotype.Service; import java.util.*; import static lk.gov.health.govcare.ai.AIIntelligenceDtos.*;
@Service public class AIIntelligenceService { private final SqlSupport sql; private final JsonSupport json; private final ClinicalPatientAccess access; public AIIntelligenceService(SqlSupport s,JsonSupport j,ClinicalPatientAccess access){sql=s;json=j;this.access=access;}
 public Map<String,Object> predict(GovCarePrincipal a,String module,PredictionRequest q){ String m=module.toLowerCase(Locale.ROOT); if(!Set.of("ckd","diabetes","cardiovascular","sepsis","readmission","length-of-stay").contains(m)) throw ApiException.badRequest("Unsupported AI prediction module."); UUID patient=sql.uuid(q.patientId(),"patientId"); a=access.clinicalScope(a,patient,true); sql.required("select id from patients where id=:p and hospital_id=:h and status<>'deleted'",Map.of("p",patient,"h",a.hospitalId()),"Patient not found."); Map<String,Object> f=q.features()==null?Map.of():q.features(); double score=score(m,f); String risk=score>=.80?"CRITICAL":score>=.60?"HIGH":score>=.35?"MODERATE":"LOW"; double confidence=Math.min(.95,.70+Math.min(f.size(),8)*.025); String rec=recommendation(m,risk); Map<String,Object> out=new LinkedHashMap<>(); out.put("risk",risk); out.put("probability",score); out.put("confidence",confidence); out.put("recommendation",rec); out.put("module",m); out.put("modelVersion","RULES-1.0-DEVELOPMENT"); String input=json.write(f), output=json.write(out); Map<String,Object> p=new HashMap<>(); p.put("h",a.hospitalId());p.put("patient",patient);p.put("type",m.toUpperCase(Locale.ROOT));p.put("input",input);p.put("output",output);p.put("risk",risk);p.put("prob",score);p.put("conf",confidence);p.put("actor",a.id()); var saved=sql.required("insert into ai_predictions(hospital_id,patient_id,prediction_type,input_data,prediction_result,risk_level,probability,confidence_score,model_version,created_by) values(:h,:patient,:type,cast(:input as jsonb),cast(:output as jsonb),:risk,:prob,:conf,'RULES-1.0-DEVELOPMENT',:actor) returning id::text",p,"Unable to save AI prediction."); String id=String.valueOf(saved.get("id")); sql.update("insert into ai_recommendations(prediction_id,recommendation_text,priority) values(cast(:id as uuid),:r,:priority)",Map.of("id",id,"r",rec,"priority",risk.equals("CRITICAL")?"URGENT":risk.equals("HIGH")?"HIGH":"ROUTINE")); p.put("id",id); sql.update("insert into ai_audit_logs(prediction_id,hospital_id,patient_id,user_id,prediction_type,input_data,output_data) values(cast(:id as uuid),:h,:patient,:actor,:type,cast(:input as jsonb),cast(:output as jsonb))",p); out.put("id",id); return out; }
 public Map<String,Object> dashboard(GovCarePrincipal a){ var visible=access.visiblePatientIds(a); if(visible.isEmpty())return Map.of("summary",Map.of("totalPredictions",0,"highRiskPatients",0,"criticalAlerts",0),"recent",List.of(),"mode","DEVELOPMENT_RULE_BASED"); var summary=sql.required("select count(*)::int \"totalPredictions\",count(*) filter(where risk_level in('HIGH','CRITICAL'))::int \"highRiskPatients\",count(*) filter(where risk_level='CRITICAL')::int \"criticalAlerts\" from ai_predictions where (:network or hospital_id=:h) and patient_id in (:visible)",listParams(a,visible),"Unable to load AI dashboard."); var recent=sql.list("select x.id::text,x.patient_id::text \"patientId\",p.patient_no \"patientNumber\",p.full_name \"patientName\",x.prediction_type \"predictionType\",x.risk_level \"riskLevel\",x.probability,x.confidence_score \"confidence\",x.created_date \"createdDate\" from ai_predictions x join patients p on p.id=x.patient_id where (:network or x.hospital_id=:h) and x.patient_id in (:visible) order by x.created_date desc limit 20",listParams(a,visible)); return Map.of("summary",summary,"recent",recent,"mode","DEVELOPMENT_RULE_BASED"); }
 public Map<String,Object> history(GovCarePrincipal a,String patientId){ UUID p=sql.uuid(patientId,"patientId"); a=access.clinicalScope(a,p,false); return Map.of("items",sql.list("select id::text,prediction_type \"predictionType\",risk_level \"riskLevel\",probability,confidence_score \"confidence\",prediction_result \"result\",created_date \"createdDate\" from ai_predictions where hospital_id=:h and patient_id=:p order by created_date desc",Map.of("h",a.hospitalId(),"p",p))); }
 private double n(Map<String,Object>f,String k){Object v=f.get(k);try{return v==null?0:Double.parseDouble(v.toString());}catch(Exception e){return 0;}}
 private double score(String m,Map<String,Object>f){
  double s=.12;
  switch(m){
   case "ckd" -> { s+=n(f,"creatinine")>2?.45:0; s+=n(f,"age")>60?.18:0; s+=n(f,"bloodUrea")>45?.15:0; }
   case "diabetes" -> { s+=n(f,"glucose")>=126?.45:0; s+=n(f,"bmi")>=30?.20:0; s+=n(f,"age")>45?.12:0; }
   case "cardiovascular" -> { s+=n(f,"systolicBloodPressure")>=140?.25:0; s+=n(f,"cholesterol")>=240?.25:0; s+=n(f,"age")>60?.18:0; }
   case "sepsis" -> { s+=n(f,"lactate")>=2?.30:0; s+=n(f,"heartRate")>100?.15:0; s+=n(f,"respiratoryRate")>22?.18:0; double spo2=n(f,"oxygenSaturation"); s+=(spo2>0&&spo2<94)?.18:0; }
   case "readmission" -> { s+=n(f,"previousAdmissions")>=2?.35:0; s+=n(f,"age")>65?.18:0; s+=n(f,"comorbidityCount")>=3?.25:0; }
   case "length-of-stay" -> { s+=n(f,"comorbidityCount")>=3?.25:0; s+=n(f,"age")>65?.15:0; s+=n(f,"severityScore")>=3?.35:0; }
   default -> { }
  }
  return Math.min(.97,s);
 }
 private String recommendation(String m,String r){if(r.equals("CRITICAL"))return "Immediate clinician review required; verify source data and assess the patient directly.";if(r.equals("HIGH"))return "Prompt clinical review recommended; correlate with current observations, laboratory results and treatment plan.";if(r.equals("MODERATE"))return "Review relevant risk factors and continue appropriate clinical monitoring.";return "Continue routine care and monitoring; reassess if the clinical condition changes.";}
 private Map<String,Object> listParams(GovCarePrincipal a,List<UUID> visible){Map<String,Object> p=new HashMap<>();p.put("hospital",a.hospitalId());p.put("h",a.hospitalId());p.put("visible",visible);p.put("network",access.canAccessNetwork(a));return p;}
}
